import json
with open('/app/resources/treasury_bulletin_2010_06.json') as f:
    data = json.load(f)

# Search for December 2010 in elements
found = []
if 'document' in data:
    doc = data['document']
    if 'elements' in doc:
        elements = doc['elements']
        for i, el in enumerate(elements):
            if isinstance(el, dict):
                # Check for Dec 2010 in any value
                for k, v in el.items():
                    if isinstance(v, str) and 'Dec. 2010' in v:
                        found.append((i, k, v[:200]))
                        break
                    elif isinstance(v, list):
                        for item in v:
                            if isinstance(item, str) and 'Dec. 2010' in item:
                                found.append((i, k, item))
                                break
print('Found Dec. 2010 in', len(found), 'elements')
for f in found[:5]:
    print(f)
