import json
with open('/app/resources/treasury_bulletin_2010_06.json') as f:
    data = json.load(f)

# Search for elements containing 'Liabilities' and table content
found_tables = []
if 'document' in data:
    doc = data['document']
    if 'elements' in doc:
        elements = doc['elements']
        for i, el in enumerate(elements):
            if isinstance(el, dict) and 'content' in el:
                content = el['content']
                if 'Liabilities to Foreigners' in content and 'Total liabilities' in content:
                    found_tables.append((i, content[:500]))
print('Found Liabilities tables:', len(found_tables))
for ft in found_tables[:5]:
    print(ft[0], ':', ft[1][:200])
